from pandas._libs import tslib

# Test case 1: near-minimum that triggers overflow on buggy
try:
    result1 = tslib.array_to_datetime(np.array(['1677-09-21T00:12:43.145224193'], dtype=object))
    probe('case_1_success', 1.0)
except OverflowError as e:
    probe('case_1_overflow', 1.0)

# Test case 2: near-minimum that also triggers overflow on buggy
try:
    result2 = tslib.array_to_datetime(np.array(['1677-09-21T00:12:43.145224999'], dtype=object))
    probe('case_2_success', 1.0)
except OverflowError as e:
    probe('case_2_overflow', 1.0)

# Test case 3: near-minimum that should succeed even on buggy
try:
    result3 = tslib.array_to_datetime(np.array(['1677-09-21T00:12:43.145225000'], dtype=object))
    probe('case_3_success', 1.0)
except OverflowError as e:
    probe('case_3_overflow', 1.0)

